//! Native select interaction retains the shared label-list authority.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,x:i32,y:i32){app.pointer_down(x,y,false);app.pointer_up(x,y);}
#[test]
fn remaining_builtin_labels_actual_app_updates_select_popup_paint_and_editor_state(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-remaining-builtin-labels-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}label{position:absolute;left:20px;top:20px;width:160px;height:24px}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}select{position:absolute;left:20px;top:100px;width:180px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}meter,output,progress{position:absolute;left:20px;top:180px}</style><body><label id=label for=absent>Initial</label><meter id=meter></meter><output id=output></output><progress id=progress></progress><select id=select><option value=first>First</option><option value=second>Second</option></select><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change labels</button><div id=destination></div><script>var tags=['meter','output','progress','select'],sources=[],lists=[],round=0;for(var tag of tags){var source=document.getElementById(tag);sources.push(source);source.id=tag+'\ud800';lists.push(source.labels);if(lists[lists.length-1].length)throw 'initial empty native list';}document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer event';var label=document.getElementById('label'),source=sources[round];if(round===1){var d=document.implementation.createHTMLDocument('source'),p=d.createElement('label');p.htmlFor=source.id;p.textContent='Output';var copy=document.importNode(p,true);copy.id='label';label.parentNode.replaceChild(copy,label);label=copy;}else if(round===2){var t=document.createElement('template');t.innerHTML='<label id=label for=seed>Progress</label>';var p=t.content.firstChild;p.htmlFor=source.id;var parent=label.parentNode;label.remove();parent.appendChild(t.content);label=p;}else{label.htmlFor=source.id;label.textContent=round===0?'Meter':'Select';}for(var at=0;at<4;at++){if(sources[at].labels!==lists[at]||lists[at].length!==(at===round?1:0))throw 'actual live builtin label lists';}if(lists[round][0]!==label||label.control!==source)throw 'current native associated control';document.title='Builtin labels '+round;round++;};sources[3].onchange=function(e){if(!e.isTrusted||this.value!=='second'||this.labels!==lists[3]||lists[3].length!==1||lists[3][0]!==document.getElementById('label'))throw 'native select event and retained list';document.title='Selected second';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");let select=(0..app.document.nodes.len()).find(|&n|matches!(&app.document.nodes[n].kind,html::NodeKind::Element{tag,..}if tag=="select")).unwrap();app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 for round in 0..4{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);let before=app.draw().pixels;click(&mut app,x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Builtin labels {round}"));assert_ne!(before,app.draw().pixels);assert_eq!(app.forms.controls[&select].value.text(),"first");let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
 assert_eq!(crate::forms::label_targets(&app.document).get(&node(&app,"label")),Some(&select));let rect=app.page.controls.iter().find(|r|r.node==select).unwrap();let(x,y)=(rect.x+8,app.content_top()+rect.y+rect.height/2-app.scroll);click(&mut app,x,y);assert!(app.select_popup.is_some());let bounds=app.select_popup_box().unwrap();let canvas=app.draw();assert_eq!(canvas.pixels[bounds.y as usize*canvas.width+bounds.x as usize],0x526d80);let popup=app.select_popup.unwrap();let choice_y=bounds.y+1+(1-popup.first)as i32*bounds.row_height+bounds.row_height/2;click(&mut app,bounds.x+10,choice_y);assert!(app.select_popup.is_none());assert_eq!(app.forms.controls[&select].value.text(),"second");assert_eq!(app.document.title,"Selected second");assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);
}
